examples.code:
lead: note("c4 e4 g4 b4").s("sawtooth").tap("line")
capture("riff", "lead/line", { window: "1b..5b" })
echo: recall("riff").add(note(12)).s("triangle").late(0.25).gain(0.5)

// The Tempo knob mirrors this setcpm. Touching the knob overrides it; the Program button next to it hands control back.
setcpm(128.8 / 4)
$: s("bd ~ ~ bd, hh*8").bank("RolandTR909")

examples.lowered:
// tap atoms.kick4 below: popover with Derive / Detach / Go to card. Graph > Rack loads this: one kick4 card (x1), one derived card, one loud card
$: s("bd*4").gain("0.8 0.6")
$: s("bd*8").gain(0.5)

examples.code:
// strudelCraft.atoms.extract(code) turns repeated strings into atoms and the references back; inline(code) undoes it
$: s("bd*4 sd")
$: s("bd*4 sd").gain(0.8)
